class TestSignatureInvariants:
    """Validate Signature dataclass structural integrity."""

    def test_required_fields_present(self, sample_signature: Signature):
        """All expected fields must exist."""
        expected_fields = {
            "name", "type", "module", "line_number", "docstring",
            "parameters", "return_type", "decorators", "dependencies"
        }
        actual_fields = {f.name for f in fields(sample_signature)}
        assert expected_fields.issubset(actual_fields), f"Missing fields: {expected_fields - actual_fields}"

    def test_immutability(self, sample_signature: Signature):
        """Signature should be immutable (frozen dataclass)."""
        with pytest.raises(Exception):
            sample_signature.name = "mutated"  # type: ignore

    def test_asdict_serialization(self, sample_signature: Signature):
        """Dataclass must serialize to dict cleanly."""
        data = asdict(sample_signature)
        assert isinstance(data, dict)
        assert data["name"] == "process_data"
        assert data["line_number"] == 42
        assert isinstance(data["parameters"], tuple)
        assert isinstance(data["decorators"], tuple)

    def test_json_roundtrip(self, sample_signature: Signature):
        """Signature must survive JSON serialization roundtrip."""
        data = asdict(sample_signature)
        json_str = json.dumps(data)
        restored = json.loads(json_str)
        assert restored["name"] == sample_signature.name
        assert tuple(restored["parameters"]) == sample_signature.parameters


