class TestCyclomaticComplexity:
    """Validate complexity computation."""

    def test_simple_function(self):
        """Simple function should have complexity 1."""
        source = "def simple():\n    return 1\n"
        tree = ast.parse(source)
        func = next(node for node in ast.walk(tree) if isinstance(node, ast.FunctionDef))
        assert _compute_cyclomatic_complexity(func) == 1

    def test_if_else_complexity(self):
        """Function with if/else should have complexity 2."""
        source = textwrap.dedent("""
            def conditional(x):
                if x > 0:
                    return "positive"
                else:
                    return "non-positive"
        """)
        tree = ast.parse(source)
        func = next(node for node in ast.walk(tree) if isinstance(node, ast.FunctionDef))
        assert _compute_cyclomatic_complexity(func) == 2

    def test_loop_complexity(self):
        """Function with for loop should have complexity 2."""
        source = textwrap.dedent("""
            def loop(items):
                total = 0
                for item in items:
                    total += item
                return total
        """)
        tree = ast.parse(source)
        func = next(node for node in ast.walk(tree) if isinstance(node, ast.FunctionDef))
        assert _compute_cyclomatic_complexity(func) == 2

    def test_nested_conditionals(self):
        """Nested conditionals should increase complexity."""
        source = textwrap.dedent("""
            def nested(x, y):
                if x > 0:
                    if y > 0:
                        return "both positive"
                    return "x positive"
                return "x non-positive"
        """)
        tree = ast.parse(source)
        func = next(node for node in ast.walk(tree) if isinstance(node, ast.FunctionDef))
        assert _compute_cyclomatic_complexity(func) == 3

    def test_complex_function(self):
        """Complex function with multiple branches."""
        source = textwrap.dedent("""
            def complex_func(a, b, c):
                if a:
                    if b:
                        return 1
                    elif c:
                        return 2
                    else:
                        return 3
                else:
                    for i in range(10):
                        if i == 5:
                            break
                    return 4
        """)
        tree = ast.parse(source)
        func = next(node for node in ast.walk(tree) if isinstance(node, ast.FunctionDef))
        complexity = _compute_cyclomatic_complexity(func)
        assert complexity >= 4  # if + nested if + elif + for + inner if


