class TestConcurrencySafety:
    """Validate thread-safe indexing behavior."""

    def test_concurrent_indexing_same_file(self, temp_python_project: Path):
        """Multiple threads indexing the same file must produce identical results."""
        module_path = temp_python_project / "main_module.py"
        indexer = CodebaseIndexer()

        def index_worker(_):
            return indexer.index_file(module_path)

        with ThreadPoolExecutor(max_workers=8) as executor:
            results = list(executor.map(index_worker, range(16)))

        # All results must be identical
        first_hash = results[0].hash
        assert all(r.hash == first_hash for r in results)
        assert all(r.module_name == results[0].module_name for r in results)

    def test_concurrent_indexing_different_files(self, temp_python_project: Path):
        """Multiple threads indexing different files must not interfere."""
        indexer = CodebaseIndexer()
        files = list(temp_python_project.glob("*.py"))

        def index_worker(path: Path):
            return indexer.index_file(path)

        with ThreadPoolExecutor(max_workers=4) as executor:
            futures = {executor.submit(index_worker, f): f for f in files}
            results = {}
            for future in as_completed(futures):
                path = futures[future]
                results[path.name] = future.result()

        assert "main_module.py" in results
        assert "helper_module.py" in results
        assert "empty_module.py" in results
        assert results["main_module.py"].module_name != results["helper_module.py"].module_name

    def test_thread_safety_of_internal_state(self, temp_python_project: Path):
        """Internal caches must remain consistent under concurrent access."""
        indexer = CodebaseIndexer()
        module_path = temp_python_project / "main_module.py"

        def index_worker(_):
            return indexer.index_file(module_path)

        with ThreadPoolExecutor(max_workers=8) as executor:
            list(executor.map(index_worker, range(32)))

        # Cache should be populated and consistent
        assert hasattr(indexer, "_cache") or hasattr(indexer, "_index_cache")
        # Verify no corruption by re-indexing
        final_result = indexer.index_file(module_path)
        assert final_result is not None


