class TestPerformanceSanity:
    """Validate performance characteristics."""

    def test_large_file_indexing(self, tmp_path: Path):
        """Large files must index within reasonable time."""
        # Generate a large Python file
        large_file = tmp_path / "large_module.py"
        lines = ["import os\n", "import json\n", "from typing import List, Dict\n", "\n"]
        for i in range(2000):
            lines.append(f"def func_{i}(x: int, y: int = {i}) -> int:\n")
            lines.append(f"    \"\"\"Function {i} docstring.\"\"\"\n")
            lines.append(f"    if x > {i}:\n")
            lines.append(f"        return x - {i}\n")
            lines.append("    else:\n")
            lines.append(f"        return y + {i}\n")
            lines.append("\n")
        large_file.write_text("".join(lines))

        indexer = CodebaseIndexer()
        start_time = time.time()
        result = indexer.index_file(large_file)
        elapsed = time.time() - start_time

        assert result is not None
        assert len(result.signatures) == 2000
        # Should index 2000 functions in under 5 seconds
        assert elapsed < 5.0, f"Indexing took {elapsed:.2f}s, expected < 5s"

    def test_complexity_bounds(self, temp_python_project: Path):
        """Complexity values must be within reasonable bounds."""
        indexer = CodebaseIndexer()
        module_path = temp_python_project / "main_module.py"
        result = indexer.index_file(module_path)

        assert 0 <= result.complexity <= 100

    def test_hash_determinism(self, temp_python_project: Path):
        """Hash must be deterministic across runs."""
        indexer = CodebaseIndexer()
        module_path = temp_python_project / "main_module.py"

        result1 = indexer.index_file(module_path)
        result2 = indexer.index_file(module_path)

        assert result1.hash == result2.hash

    def test_hash_sensitivity(self, tmp_path: Path):
        """Hash must change when content changes."""
        module = tmp_path / "mod.py"
        module.write_text("def foo():\n    return 1\n")

        indexer = CodebaseIndexer()
        hash1 = indexer.index_file(module).hash

        module.write_text("def foo():\n    return 2\n")
        hash2 = indexer.index_file(module).hash

        assert hash1 != hash2


