@pytest.mark.skipif(not HYPOTHESIS_AVAILABLE, reason="Hypothesis not installed")
class TestPropertyBased:
    """Property-based tests for structural invariants."""

    @settings(max_examples=50, suppress_health_check=[HealthCheck.too_slow])
    @given(
        st.text(min_size=1, max_size=50),
        st.integers(min_value=1, max_value=10000),
        st.lists(st.text(min_size=1, max_size=20), min_size=0, max_size=10)
    )
    def test_signature_construction(self, name: str, line: int, params: List[str]):
        """Signature must accept valid inputs and maintain invariants."""
        sig = Signature(
            name=name,
            type="function",
            module="test.module",
            line_number=line,
            docstring="",
            parameters=tuple((p, "Any") for p in params),
            return_type="Any",
            decorators=(),
            dependencies=(),
        )
        assert sig.name == name
        assert sig.line_number == line
        assert len(sig.parameters) == len(params)

    @settings(max_examples=20, suppress_health_check=[HealthCheck.too_slow])
    @given(st.text(min_size=1, max_size=100))
    def test_complexity_non_negative(self, source_code: str):
        """Complexity must never be negative."""
        try:
            tree = ast.parse(source_code)
        except SyntaxError:
            return  # Skip invalid Python

        for node in ast.walk(tree):
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                complexity = _compute_cyclomatic_complexity(node)
                assert complexity >= 1


